modules.content:
mock_provider "azurerm" {}

variables {
  name = "log-tp-test"
  resource_group_name = "rg-test"
  location = "westeurope"
}

run "names_the_workspace" {
  command = plan
  assert {
    condition     = azurerm_log_analytics_workspace.this.name == "log-tp-test"
    error_message = "name mismatch"
  }
}
